"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines


def _include_target(line):
    parts = line.split(None, 1)
    if parts and parts[0] == "@include":
        return parts[1].strip() if len(parts) > 1 else ""
    return None


def _read_lines(path, stack):
    real = os.path.realpath(path)
    with open(path, "r", encoding="utf-8") as fh:
        raw_lines = fh.read().splitlines()
    if not any(_include_target(raw) is not None for raw in raw_lines):
        return raw_lines
    stack = stack + (real,)
    base = os.path.dirname(real)
    out = []
    for raw in raw_lines:
        target = _include_target(raw)
        if target is None:
            out.append(raw)
            continue
        if not target:
            raise ConfigError("{}: @include requires a path".format(path))
        inc_path = os.path.join(base, target)
        inc_real = os.path.realpath(inc_path)
        if inc_real in stack:
            raise ConfigError("include cycle detected: {}".format(inc_path))
        if not os.path.isfile(inc_path):
            raise ConfigError("include file not found: {}".format(inc_path))
        try:
            out.extend(_read_lines(inc_path, stack))
        except (OSError, UnicodeDecodeError) as exc:
            raise ConfigError(
                "cannot read include file {}: {}".format(inc_path, exc)
            )
    return out


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are expanded inline, recursively, with paths
    resolved relative to the including file.
    """
    return parse_lines(_read_lines(path, ()))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
